from mpmath import mp, mpf

mp.dps = 10000

# 2000 digits
reference = mpf('0.')

def match_count(A: str, B: str):
    n = 0
    for a, b in zip(A, B):
        if a != b:
            break
        n += 1
    return n

data = [
    (50, 276, mpf('0.11494204485329620070104015746959874283079533720086353')),
    (100, 560, mpf('0.1149420448532962007010401574695987428307953372008635168440233965189660128253530511779407724849711769435')),
    (150, 842, mpf('0.114942044853296200701040157469598742830795337200863516844023396518966012825353051177940772484985836993763476746144549297143628513363520837125510628299633')),
    (200, 1126, mpf('0.11494204485329620070104015746959874283079533720086351684402339651896601282535305117794077248498583699376347674614454929714362851336352083713226251291416490606379826713224843083938616761045998547463408051')),
    (250, 1408, mpf('0.1149420448532962007010401574695987428307953372008635168440233965189660128253530511779407724849858369937634767461445492971436285133635208371322625129141649060637982671322484308393861678241340525286712589371746001928400815089309259784102954199605104036699')),
    (300, 1692, mpf('0.')),
    (350, 1976, mpf('0.')),
    (400, 2260, mpf('0.')),
    (450, 2542, mpf('0.')),
    (500, 2826, mpf('0.')),
    (550, 3110, mpf('0.')),
    (600, 3394, mpf('0.')),
    (650, 3678, mpf('0.')),
    (700, 3962, mpf('0.')),
    (750, 4246, mpf('0.')),
    (800, 4530, mpf('0.')),
    (850, 4812, mpf('0.')),
    (900, 5096, mpf('0.')),
    (950, 5380, mpf('0.')),
    (1000, 5664, mpf('0.')),
    (1050, 5948, mpf('0.')),
    (1100, 6232, mpf('0.')),
    (1150, 6516, mpf('0.')),
    (1200, 6800, mpf('0.')),
]

precisions = []
itercounts = []
values = []
match_counts = []

for precision, itercount, value in data:
    precisions.append(precision)
    itercounts.append(itercount)
    values.append(value)
    match_counts.append(match_count(str(reference)[2:], str(value)[2:]))

match_ratio = [a / b for a, b in zip(match_counts, precisions)]

from matplotlib import pyplot

pyplot.plot(precisions, itercounts, label='itercounts')
pyplot.plot(precisions, match_counts, label='match counts')
pyplot.legend()
pyplot.show()

pyplot.plot(precisions, match_ratio, label='match_ratio')
pyplot.legend()
pyplot.show()
